import type { OpenAPIObject } from '@nestjs/swagger';

const TAG_PREFIX = 'Better Auth';

/**
 * Merges the OpenAPI schema generated by Better Auth's `openAPI()` plugin into the
 * Nest-generated document, so both live in a single interactive reference.
 *
 * Better Auth paths are relative to its base path (e.g. `/sign-in/email`), so they are
 * re-rooted under `authBasePath` (e.g. `/api/v1/auth`). Existing Nest entries always win.
 */
export function mergeAuthOpenApi(
  document: OpenAPIObject,
  authSchema: any,
  authBasePath: string,
): OpenAPIObject {
  if (!authSchema?.paths) return document;

  const base = `/${authBasePath.replace(/^\/+|\/+$/g, '')}`;
  const authSecurity: Record<string, string[]>[] = authSchema.security ?? [];
  const usedTags = new Map<string, string | undefined>();

  document.paths ??= {};
  for (const [path, item] of Object.entries<Record<string, any>>(authSchema.paths)) {
    const fullPath = `${base}${path}`;
    if (document.paths[fullPath]) continue;

    const operations: Record<string, any> = {};
    for (const [method, operation] of Object.entries<any>(item)) {
      const tags = (operation.tags ?? ['Default']).map((tag: string) => `${TAG_PREFIX} - ${tag}`);
      for (const tag of tags) {
        const original = tag.slice(TAG_PREFIX.length + 3);
        usedTags.set(
          tag,
          authSchema.tags?.find((t: { name: string }) => t.name === original)?.description,
        );
      }
      operations[method] = {
        ...operation,
        tags,
        security: operation.security ?? authSecurity,
      };
    }
    document.paths[fullPath] = operations;
  }

  document.tags = [
    ...(document.tags ?? []),
    ...[...usedTags].map(([name, description]) => ({ name, description })),
  ];

  document.components ??= {};
  document.components.schemas = {
    ...authSchema.components?.schemas,
    ...document.components.schemas,
  };
  document.components.securitySchemes = {
    ...authSchema.components?.securitySchemes,
    ...document.components.securitySchemes,
  };

  return document;
}
